// blockchain/logger.js
const { ethers } = require("ethers");

/**
 * Configure these three variables after spinning up Ganache and deploying the contract.
 * We will use a standard local HTTP provider pointing to 127.0.0.1:8545 (or 7545 for Ganache UI)
 */
const GANACHE_RPC_URL = "http://127.0.0.1:7545"; // Ganache CLI default; if using Ganache App, it's usually 7545
const PRIVATE_KEY = "0x85c17fb8175a9b69a6db671d4f8c070581256c869e07897343ce3b7c6f21d22c";
const CONTRACT_ADDRESS = "0xbDd0Db1246E4262fcF29569b691B3868d804B726";

// The ABI (Application Binary Interface) generated by Solidity compiler for EligibilityLogger
const CONTRACT_ABI = [
  "function logAssessment(string _caseId, string _dataSources, string _reasoningChain, uint8 _confidenceLevel, string _paralegalResponse)",
  "function getLogCount(string _caseId) view returns (uint256)",
  "function getLog(string _caseId, uint256 index) view returns (string, string, uint8, string, uint256, address)",
  "event LogCreated(string indexed caseId, uint8 confidenceLevel, string paralegalResponse, uint256 timestamp)"
];

async function main() {
  // 1. Connect to Ganache network
  const provider = new ethers.JsonRpcProvider(GANACHE_RPC_URL);

  // 2. Load the Paralegal's or System's Wallet using the private key
  const wallet = new ethers.Wallet(PRIVATE_KEY, provider);
  console.log(`🔗 Connected with Wallet Address: ${wallet.address}`);

  // 3. Connect to the deployed smart contract
  const contract = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, wallet);

  // 4. Define our mock data matching Pillar 05 requirements
  const mockCaseId = "CASE-1b4e5-992a";
  const dataSources = "eCourts Portal, NJDG Database, FIR OCR";
  const reasoningChain = "Case mapped to Section 479 BNSS. Max sentence 3 years. Detained 14 months > 1/3 threshold. Eligible.";
  const confidenceLevel = 94; // 94%
  const paralegalResponse = "Acted On - Bail Application Filed";

  console.log("📝 Writing immutable AI assessment log to Ganache Blockchain...");

  // 5. Execute the state-changing transaction on the Blockchain
  try {
    const tx = await contract.logAssessment(
      mockCaseId,
      dataSources,
      reasoningChain,
      confidenceLevel,
      paralegalResponse
    );

    console.log(`⏳ Transaction sent! Hash: ${tx.hash}`);
    console.log("Waiting for block confirmation...");
    
    // Wait for the transaction to be mined (Ganache is instant usually)
    const receipt = await tx.wait();
    console.log(`✅ Success! Block logged in block: ${receipt.blockNumber}`);

    // --- VERIFICATION: Read the log back from the blockchain ---
    console.log("\n🔍 Reading the log back from the Smart Contract...");
    const logCount = await contract.getLogCount(mockCaseId);
    console.log(`Total immutable logs for ${mockCaseId}: ${logCount}`);

    // Array is 0-indexed, so we fetch the most recent one we just pushed
    const recentIndex = logCount - 1n; 
    const logResult = await contract.getLog(mockCaseId, recentIndex);

    // logResult returns a tuple: (dataSources, reasoning, confidence, paralegalResponse, timestamp, loggedBy)
    const timestamp = new Date(Number(logResult[4]) * 1000).toLocaleString();

    console.log({
      dataSources: logResult[0],
      reasoningChain: logResult[1],
      confidence: `${logResult[2]}%`,
      actionTaken: logResult[3],
      immutableTimestamp: timestamp,
      signedBy: logResult[5]
    });

  } catch (error) {
    console.error("❌ Failed to log transaction:", error);
  }
}

// Run the script
if (require.main === module) {
    if (PRIVATE_KEY.includes("REPLACE") || CONTRACT_ADDRESS.includes("REPLACE")) {
        console.log("⚠️ PLEASE REPLACE YOUR PRIVATE_KEY AND CONTRACT_ADDRESS BEFORE RUNNING");
    } else {
        main();
    }
}
